import{_ as e,o as a,c as o,ai as r}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Tool calls","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/tool-calls.md","filePath":"en/guide/tool-calls.md"}'),n={name:"en/guide/tool-calls.md"};function s(l,t,h,d,i,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="tool-calls" tabindex="-1">Tool calls <a class="header-anchor" href="#tool-calls" aria-label="Permalink to &quot;Tool calls&quot;">​</a></h1><p>The <strong>Tool calls</strong> page asks one question of a local model: can it call a tool the way an agent needs? Thirteen request shapes agents send all day, scored on what the daemon returned.</p><p><strong>Sidebar item:</strong> Tool calls (below GPU map) <strong>Route:</strong> <code>/tool-calls</code><strong>Added in:</strong> v0.8.0 (October 2026) <strong>Requires:</strong> a model that supports tools. Models that report tool support are listed first; any chat model can be ticked.</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>Agent frameworks live or die on tool calls, and local models fail them in ways a score on a public benchmark never shows: the right tool with an argument missing, a number sent as a string, the call written into the answer text where the framework never sees it, a call to a tool that does not exist, a tool called when none was needed. Each of those breaks an agent in a different way.</p><p>The suite was born from a measured failure: a 7.5B model dropped the required <code>path</code> argument whenever the <code>content</code> argument it was writing was long. That case is in the suite in the shape that broke it.</p><h2 id="the-cases" tabindex="-1">The cases <a class="header-anchor" href="#the-cases" aria-label="Permalink to &quot;The cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>What it checks</th></tr></thead><tbody><tr><td>One tool, one argument</td><td>The floor.</td></tr><tr><td>A long argument next to a short one</td><td>The short required argument survives a long one, with five tools on offer.</td></tr><tr><td>An argument restricted to a list</td><td>The value is from the list.</td></tr><tr><td>A number must be a number</td><td>Not a quoted string.</td></tr><tr><td>A nested object argument</td><td>Dates and times inside an object.</td></tr><tr><td>Two tools, pick the right one</td><td>The right tool among three.</td></tr><tr><td>Eight tools on offer, pick the right one</td><td>The right tool when the schemas crowd the prompt.</td></tr><tr><td>No tool is needed</td><td>A greeting gets an answer, not a call.</td></tr><tr><td>Two calls in one turn</td><td>Independent reads batched.</td></tr><tr><td>Answer after a tool result</td><td>The second half of the loop: use the result, do not call again.</td></tr><tr><td>An argument with accents and spaces</td><td>The path survives.</td></tr><tr><td>Leave an optional argument out</td><td>No invented value.</td></tr><tr><td>Only the tools that exist</td><td>No call to a tool that was never offered.</td></tr></tbody></table><p>Every case runs at temperature 0, non-streaming, through <code>/api/chat</code>, the way an agent would send it.</p><h2 id="reading-the-results" tabindex="-1">Reading the results <a class="header-anchor" href="#reading-the-results" aria-label="Permalink to &quot;Reading the results&quot;">​</a></h2><p>One column per model with its share of cases right. One row per case, with why it matters. Each cell is one sentence: &quot;the path argument is missing&quot;, &quot;wrote the call into the answer text&quot;, &quot;called search_web when no tool was needed&quot;. Click a cell and the answer opens under the row: the tool calls the model emitted, the text it wrote, and, when the daemon returned it, what the model thought first.</p><p>A correct tool call has no answer text. The call is the answer. The page says so where it applies.</p><p>The last run is kept in the browser; running again replaces it.</p><h2 id="what-the-page-does-not-know" tabindex="-1">What the page does not know <a class="header-anchor" href="#what-the-page-does-not-know" aria-label="Permalink to &quot;What the page does not know&quot;">​</a></h2><p>Whether a tool call would have worked once executed. It judges the call itself, against the schema the model was given, the way a framework does before running anything.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live.html">Live</a> shows the tool calls your real agents make, turn by turn.</li><li><a href="./benchmark.html">Benchmark</a> for the question-and-answer suites.</li></ul>',17)])])}const p=e(n,[["render",s]]);export{g as __pageData,p as default};
